"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Wallet, ArrowUpCircle, ArrowDownCircle, Search, 
  Plus, Filter, X, Target
} from "lucide-react";
import TourGuide from "@/components/TourGuide";
// Import Action Server
import { createGeneralTrx, createEventBudget, createEventTrx } from "@/lib/actions";

// DEFINISI LANGKAH TUR (Sama kayak punya Koh)
const kasTourSteps = [
    { target: '.tour-kas-header', content: 'Pusat pengelolaan dana organisasi.', disableBeacon: true },
    { target: '.tour-tab-switcher', content: 'Pindah antara Kas Umum & Anggaran Event.' },
    { target: '.tour-stats-bar', content: 'Pantau Saldo & Arus Kas real-time.', placement: 'bottom' as const },
    { target: '.tour-trx-buttons', content: 'Catat transaksi baru.', },
    { target: '.tour-trx-table', content: 'Riwayat transaksi tercatat di sini.', },
];

const formatIDR = (val: number) => new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(val);

// Props dari Server
export default function KeuanganClient({ generalTrx, events, prokers }: { generalTrx: any[], events: any[], prokers: any[] }) {
  const [activeTab, setActiveTab] = useState<'general' | 'events'>('general');
  const [isClient, setIsClient] = useState(false); 
  
  // STATE MODAL & FORM
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalType, setModalType] = useState<'general_in' | 'general_out' | 'new_event' | 'event_trx'>('general_in');
  const [selectedEventId, setSelectedEventId] = useState<number | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  const [formData, setFormData] = useState<any>({ title: "", amount: "", date: "", category: "Umum", pic: "", prokerId: "", isSubsidi: false });

  useEffect(() => { setIsClient(true); }, []);

  // HITUNG SALDO KAS UMUM (Client Side Calculation)
  const totalMasuk = generalTrx.filter(t => t.type === 'PEMASUKAN').reduce((acc, curr) => acc + curr.amount, 0);
  const totalKeluar = generalTrx.filter(t => t.type === 'PENGELUARAN').reduce((acc, curr) => acc + curr.amount, 0);
  const saldoUmum = totalMasuk - totalKeluar;

  // --- ACTIONS ---
  const handleOpenGeneralModal = (type: 'in' | 'out') => {
    setModalType(type === 'in' ? 'general_in' : 'general_out');
    setFormData({ title: "", amount: "", date: new Date().toISOString().split('T')[0], category: "Umum", pic: "", prokerId: "", isSubsidi: false });
    setIsModalOpen(true);
  };

  const handleOpenNewEventModal = () => {
    setModalType('new_event');
    setFormData({ title: "", amount: "", date: new Date().toISOString().split('T')[0], prokerId: "", isSubsidi: false }); 
    setIsModalOpen(true);
  };

  const handleOpenEventTrxModal = (eventId: number) => {
    setSelectedEventId(eventId);
    setModalType('event_trx');
    setFormData({ title: "", amount: "", date: new Date().toISOString().split('T')[0], prokerId: "", isSubsidi: false });
    setIsModalOpen(true);
  };

  // --- SUBMIT HANDLER (TERKONEKSI DB) ---
  const handleSubmit = async () => {
    const isNewEvent = modalType === 'new_event';
    if (!formData.amount || (!formData.title && !formData.prokerId)) return alert("Data tidak lengkap!");
    
    setIsSubmitting(true);

    const data = new FormData();
    
    // Jika link ke proker, ambil nama prokernya buat judul transaksi
    let finalTitle = formData.title;
    if (isNewEvent && formData.prokerId) {
        const p = prokers.find(x => x.id === Number(formData.prokerId));
        finalTitle = p?.nama || "Anggaran Proker";
        data.append("prokerId", formData.prokerId);
    }

    data.append("title", finalTitle);
    data.append("amount", formData.amount);
    data.append("date", formData.date);

    let result;

    try {
        if (modalType === 'general_in' || modalType === 'general_out') {
            data.append("type", modalType === 'general_in' ? "PEMASUKAN" : "PENGELUARAN");
            data.append("category", formData.category);
            data.append("pic", formData.pic || "Admin");
            result = await createGeneralTrx(data);
        } 
        else if (modalType === 'new_event') {
            if(formData.isSubsidi && Number(formData.amount) > saldoUmum) {
                setIsSubmitting(false);
                return alert("Saldo Kas Umum tidak cukup untuk subsidi!");
            }
            data.append("isSubsidi", String(formData.isSubsidi));
            result = await createEventBudget(data);
        } 
        else if (modalType === 'event_trx' && selectedEventId) {
            data.append("eventId", selectedEventId.toString());
            result = await createEventTrx(data);
        }

        if (result?.success) {
            setIsModalOpen(false);
            window.location.reload(); 
        } else {
            alert("Gagal: " + result?.message);
        }
    } catch (e) {
        console.error(e);
        alert("Terjadi kesalahan.");
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col gap-6 font-sans">
      
      {/* HEADER & TABS (FIXED) */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-4 shrink-0 px-4 md:px-0">
         <div>
            <div className="flex items-center gap-4 mb-1">
               <h1 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight flex items-center gap-3 tour-kas-header">
                  Keuangan OSIS <span className="text-2xl p-2 bg-yellow-100 dark:bg-yellow-900/30 rounded-full">💰</span>
               </h1>
               {isClient && <TourGuide steps={kasTourSteps} />}
            </div>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">Kelola Kas Umum dan Anggaran Kegiatan.</p>
         </div>
         
         <div className="flex bg-slate-100 dark:bg-[#1e293b] p-1 rounded-xl border border-slate-200 dark:border-white/10 tour-tab-switcher">
            <button onClick={() => setActiveTab('general')} className={`px-6 py-2.5 rounded-lg text-xs font-bold transition-all ${activeTab === 'general' ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-white shadow-sm' : 'text-slate-500 hover:text-slate-800 dark:hover:text-slate-300'}`}>Buku Kas Umum</button>
            <button onClick={() => setActiveTab('events')} className={`px-6 py-2.5 rounded-lg text-xs font-bold transition-all ${activeTab === 'events' ? 'bg-white dark:bg-slate-700 text-purple-600 dark:text-white shadow-sm' : 'text-slate-500 hover:text-slate-800 dark:hover:text-slate-300'}`}>Anggaran Event</button>
         </div>
      </div>

      <div className="flex-1 bg-white dark:bg-[#0f172a] md:rounded-2xl border-y md:border border-slate-200 dark:border-white/5 shadow-sm overflow-hidden flex flex-col mx-[-16px] md:mx-0">
         
         {/* TAB 1: KAS UMUM */}
         {activeTab === 'general' && (
            <>
               <div className="p-6 border-b border-slate-100 dark:border-white/5 grid grid-cols-1 md:grid-cols-3 gap-6 bg-slate-50/50 dark:bg-white/5 tour-stats-bar">
                  <div className="flex items-center gap-4">
                     <div className="p-3 bg-blue-100 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400 rounded-xl"><Wallet size={24}/></div>
                     <div><p className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">Saldo Akhir</p><h2 className="text-2xl font-bold text-slate-900 dark:text-white">{formatIDR(saldoUmum)}</h2></div>
                  </div>
                  <div className="flex items-center gap-4">
                     <div className="p-3 bg-emerald-100 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 rounded-xl"><ArrowUpCircle size={24}/></div>
                     <div><p className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">Pemasukan</p><h2 className="text-xl font-bold text-emerald-600">{formatIDR(totalMasuk)}</h2></div>
                  </div>
                  <div className="flex items-center gap-4">
                     <div className="p-3 bg-rose-100 dark:bg-rose-500/20 text-rose-600 dark:text-rose-400 rounded-xl"><ArrowDownCircle size={24}/></div>
                     <div><p className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">Pengeluaran</p><h2 className="text-xl font-bold text-rose-600">{formatIDR(totalKeluar)}</h2></div>
                  </div>
               </div>

               <div className="px-6 py-4 flex justify-between items-center border-b border-slate-100 dark:border-white/5">
                  <h3 className="text-sm font-bold text-slate-800 dark:text-white">Riwayat Transaksi</h3>
                  <div className="flex gap-2 tour-trx-buttons">
                     <button onClick={() => handleOpenGeneralModal('in')} className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold flex items-center gap-2 transition-all active:scale-95"><Plus size={14}/> Masuk</button>
                     <button onClick={() => handleOpenGeneralModal('out')} className="px-4 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-lg text-xs font-bold flex items-center gap-2 transition-all active:scale-95"><ArrowDownCircle size={14}/> Keluar</button>
                  </div>
               </div>

               <div className="flex-1 overflow-auto custom-scrollbar tour-trx-table">
                  <table className="w-full text-left border-collapse">
                     <thead className="bg-slate-50 dark:bg-white/5 sticky top-0 z-10 border-b border-slate-100 dark:border-white/5">
                        <tr>
                           <th className="p-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-6">Tanggal</th>
                           <th className="p-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Keterangan</th>
                           <th className="p-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Kategori</th>
                           <th className="p-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest text-right pr-6">Nominal</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-50 dark:divide-white/5">
                        {generalTrx.length === 0 ? (
                            <tr><td colSpan={4} className="p-12 text-center text-slate-400 text-xs font-medium">Belum ada aktivitas transaksi yang tercatat</td></tr>
                        ) : (
                            generalTrx.map(t => (
                               <tr key={t.id} className="hover:bg-slate-50/80 dark:hover:bg-white/5 transition-colors">
                                  <td className="p-4 text-[11px] font-medium text-slate-500 pl-6">{t.date}</td>
                                  <td className="p-4">
                                      <p className="text-sm font-bold text-slate-800 dark:text-slate-200">{t.title}</p>
                                      <p className="text-[10px] font-medium text-slate-400 uppercase tracking-tighter">{t.pic}</p>
                                  </td>
                                  <td className="p-4">
                                      <span className="px-2.5 py-1 bg-slate-100 dark:bg-white/5 rounded-md text-[10px] font-bold text-slate-500 border border-slate-200 dark:border-white/5">{t.category}</span>
                                  </td>
                                  <td className={`p-4 text-right font-bold pr-6 ${t.type === 'PEMASUKAN' ? 'text-emerald-600' : 'text-rose-600'}`}>
                                      {t.type === 'PEMASUKAN' ? '+' : '-'} {formatIDR(t.amount)}
                                  </td>
                               </tr>
                            ))
                        )}
                     </tbody>
                  </table>
               </div>
            </>
         )}

         {/* TAB 2: ANGGARAN EVENT */}
         {activeTab === 'events' && (
            <div className="flex flex-col h-full">
               <div className="p-6 border-b border-slate-100 dark:border-white/5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-slate-50/30">
                  <div>
                     <h3 className="text-lg font-bold text-slate-900 dark:text-white">Manajemen Anggaran Kegiatan</h3>
                     <p className="text-xs font-medium text-slate-500 mt-0.5">Alokasikan dana khusus untuk Program Kerja organisasi.</p>
                  </div>
                  <button onClick={handleOpenNewEventModal} className="px-5 py-2.5 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-bold text-xs shadow-lg shadow-purple-500/20 flex items-center gap-2 transition-all active:scale-95">
                     <Plus size={16}/> Alokasi Anggaran Baru
                  </button>
               </div>

               <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                  {events.length === 0 ? (
                      <div className="h-full flex flex-col items-center justify-center text-center p-12 opacity-40">
                          <Target size={48} className="mb-4 text-slate-300" />
                          <p className="text-sm font-medium text-slate-500">Belum ada Program Kerja yang memiliki anggaran.</p>
                      </div>
                  ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {events.map(ev => {
                            const percent = ev.budget > 0 ? Math.round((ev.used / ev.budget) * 100) : 0;
                            const sisa = ev.budget - ev.used;
                            const isClosed = ev.status === 'DONE' || ev.status === 'BATAL';

                            return (
                            <div key={ev.id} className={`rounded-2xl border p-5 shadow-sm relative overflow-hidden transition-all group ${isClosed ? 'bg-slate-50 border-slate-200 opacity-60' : 'bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 hover:shadow-md hover:border-purple-200 dark:hover:border-purple-500/30'}`}>
                                <div className="flex justify-between items-start mb-4">
                                    <div className={`p-3 rounded-xl ${isClosed ? 'bg-slate-200 text-slate-500' : 'bg-purple-100 dark:bg-purple-500/20 text-purple-600'}`}><Target size={24}/></div>
                                    <span className={`text-[9px] font-bold px-2 py-0.5 rounded-full border ${ev.status === 'DONE' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-blue-50 text-blue-600 border-blue-100'}`}>{ev.status}</span>
                                </div>

                                <h3 className="text-base font-bold text-slate-900 dark:text-white mb-1">{ev.name}</h3>
                                <p className="text-[11px] font-medium text-slate-500 mb-5 flex items-center gap-1.5">Total Anggaran: <span className="font-bold text-slate-700 dark:text-slate-300">{formatIDR(ev.budget)}</span></p>

                                <div className="space-y-2 mb-6 bg-slate-50 dark:bg-white/5 p-4 rounded-xl border border-slate-100 dark:border-white/5">
                                    <div className="flex justify-between text-[10px] font-bold uppercase tracking-wider">
                                        <span className="text-slate-500">Realisasi ({percent}%)</span>
                                        <span className="text-purple-600">{formatIDR(ev.used)}</span>
                                    </div>
                                    <div className="w-full h-1.5 bg-slate-200 dark:bg-white/10 rounded-full overflow-hidden">
                                        <motion.div initial={{ width: 0 }} animate={{ width: `${percent}%` }} transition={{ duration: 1 }} className={`h-full rounded-full ${percent > 90 ? 'bg-rose-500' : 'bg-purple-500'}`}></motion.div>
                                    </div>
                                    <div className="text-right text-[10px] font-bold text-emerald-600">Sisa Dana: {formatIDR(sisa)}</div>
                                </div>

                                <div className="pt-2">
                                    {!isClosed && (
                                        <button onClick={() => handleOpenEventTrxModal(ev.id)} className="w-full py-2.5 rounded-xl border border-dashed border-slate-300 dark:border-white/10 hover:border-purple-400 hover:bg-purple-50 dark:hover:bg-purple-900/10 text-slate-400 hover:text-purple-600 text-[11px] font-bold transition-all flex items-center justify-center gap-2 mb-4">
                                            <Plus size={14}/> Catat Pengeluaran
                                        </button>
                                    )}
                                    
                                    <div className="space-y-2 border-t border-slate-100 dark:border-white/5 pt-4">
                                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-2">Aktivitas Terakhir</p>
                                        {ev.transactions.length === 0 ? (
                                            <p className="text-[10px] text-slate-400 italic">Belum ada pengeluaran</p>
                                        ) : (
                                            ev.transactions.slice(0, 3).map((t:any) => (
                                            <div key={t.id} className="flex justify-between items-center text-[10px] font-medium bg-white dark:bg-transparent p-1">
                                                <span className="text-slate-600 dark:text-slate-400 truncate w-2/3 flex items-center gap-2"><div className="w-1 h-1 rounded-full bg-slate-300"></div> {t.title}</span>
                                                <span className="font-bold text-rose-500">-{formatIDR(t.amount)}</span>
                                            </div>
                                            ))
                                        )}
                                    </div>
                                </div>
                            </div>
                            );
                        })}
                    </div>
                  )}
               </div>
            </div>
         )}
      </div>

      {/* === MODAL UNIVERSAL === */}
      <AnimatePresence>
         {isModalOpen && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
               <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm"/>
               <motion.div initial={{ scale: 0.95, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.95, opacity: 0, y: 20 }} className="relative w-full max-w-md bg-white dark:bg-[#0f172a] rounded-2xl shadow-2xl overflow-hidden border border-white/10">
                  
                  <div className={`p-6 border-b flex justify-between items-center ${
                      modalType === 'general_in' ? 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-700 dark:text-emerald-400' : 
                      modalType.includes('out') || modalType === 'event_trx' ? 'bg-rose-50 dark:bg-rose-500/10 text-rose-700 dark:text-rose-400' : 
                      'bg-purple-50 dark:bg-purple-500/10 text-purple-700 dark:text-purple-400'
                  }`}>
                     <div>
                        <h2 className="text-base font-bold">
                           {modalType === 'general_in' && 'Tambah Pemasukan Kas'}
                           {modalType === 'general_out' && 'Tambah Pengeluaran Kas'}
                           {modalType === 'new_event' && 'Alokasi Dana Proker'}
                           {modalType === 'event_trx' && 'Realisasi Anggaran Event'}
                        </h2>
                        <p className="text-[10px] font-medium opacity-70 mt-0.5">Lengkapi rincian transaksi di bawah ini.</p>
                     </div>
                     <button onClick={() => setIsModalOpen(false)} className="hover:bg-black/5 dark:hover:bg-white/5 p-2 rounded-xl transition-colors"><X size={18}/></button>
                  </div>

                  <div className="p-7 space-y-5">
                     {/* INPUT KHUSUS NEW EVENT (Pilih Proker atau Tulis Baru) */}
                     {modalType === 'new_event' && (
                        <div>
                           <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2 block">Pilih Program Kerja</label>
                           <select 
                             value={formData.prokerId} 
                             onChange={e => setFormData({...formData, prokerId: e.target.value})} 
                             className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-purple-500 dark:text-white text-xs font-bold transition-all"
                           >
                              <option value="">-- Buat Event/Proker Baru --</option>
                              {prokers.map(p => (
                                 <option key={p.id} value={p.id}>{p.nama}</option>
                              ))}
                           </select>
                           {!formData.prokerId && (
                               <div className="mt-4">
                                   <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2 block">Nama Event Baru</label>
                                   <input type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-purple-500 dark:text-white text-xs font-bold" placeholder="Contoh: LDKS 2026" />
                               </div>
                           )}
                        </div>
                     )}

                     {modalType !== 'new_event' && (
                        <div>
                           <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2 block">Keterangan Transaksi</label>
                           <input autoFocus type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-xs font-bold" placeholder="..." />
                        </div>
                     )}
                     
                     <div>
                        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2 block">
                           {modalType === 'new_event' ? 'Jumlah Dana Dialokasikan' : 'Nominal Transaksi (Rp)'}
                        </label>
                        <div className="relative">
                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-400">Rp</span>
                            <input type="number" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full pl-10 pr-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-xs font-bold" placeholder="0" />
                        </div>
                        {modalType === 'new_event' && (
                            <div className="mt-4 p-4 bg-amber-50 dark:bg-amber-500/10 rounded-xl border border-amber-100 dark:border-amber-500/20">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-lg ${formData.isSubsidi ? 'bg-amber-500 text-white' : 'bg-slate-200 dark:bg-white/10 text-slate-400'}`}><Wallet size={16} /></div>
                                        <div>
                                            <p className="text-[10px] font-bold text-slate-900 dark:text-white uppercase tracking-tight">Ambil dari Kas Umum?</p>
                                            <p className="text-[9px] font-medium text-slate-500 leading-tight">Gunakan Kas Umum sebagai dana darurat/subsidi.</p>
                                        </div>
                                    </div>
                                    <button type="button" onClick={() => setFormData({...formData, isSubsidi: !formData.isSubsidi})} className={`w-10 h-5 rounded-full transition-all relative ${formData.isSubsidi ? 'bg-amber-500' : 'bg-slate-300 dark:bg-white/10'}`}><div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full transition-all ${formData.isSubsidi ? 'left-5.5' : 'left-0.5'}`} /></button>
                                </div>
                                {formData.isSubsidi && <p className="text-[9px] font-bold text-amber-600 mt-2 flex items-center gap-1.5"><ArrowDownCircle size={10}/> Dana akan dipotong dari Saldo Kas Umum.</p>}
                                {!formData.isSubsidi && <p className="text-[9px] font-bold text-blue-600 mt-2 flex items-center gap-1.5">🏫 Dana akan dicatat sebagai Anggaran Sekolah.</p>}
                            </div>
                        )}
                     </div>

                     <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                           <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-0.5 block">Tanggal</label>
                           <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-[11px] font-bold" />
                        </div>
                        {modalType.includes('general') && (
                           <div className="space-y-2">
                              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-0.5 block">Kategori</label>
                              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-[11px] font-bold">
                                 <option>Umum</option><option>Dana Sekolah</option><option>Sponsorship</option><option>Iuran Anggota</option><option>Lainnya</option>
                              </select>
                           </div>
                        )}
                        {modalType.includes('general') && (
                           <div className="col-span-2 space-y-2">
                              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-0.5 block">PIC / Penanggung Jawab</label>
                              <input type="text" value={formData.pic} onChange={e => setFormData({...formData, pic: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 dark:text-white text-[11px] font-bold" placeholder="Nama pengurus..." />
                           </div>
                        )}
                     </div>
                  </div>

                  <div className="p-6 border-t border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/5 flex justify-end gap-3">
                     <button onClick={() => setIsModalOpen(false)} disabled={isSubmitting} className="px-5 py-2.5 rounded-xl text-xs font-bold text-slate-500 hover:bg-slate-200 dark:hover:bg-white/5 transition-colors">Batal</button>
                     <button onClick={handleSubmit} disabled={isSubmitting} className={`px-7 py-2.5 rounded-xl text-white text-xs font-bold shadow-lg transition-all active:scale-95 ${
                         modalType === 'general_in' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-500/20' : 
                         modalType.includes('out') || modalType === 'event_trx' ? 'bg-rose-600 hover:bg-rose-700 shadow-rose-500/20' : 
                         'bg-purple-600 hover:bg-purple-700 shadow-purple-500/20'
                     }`}>
                        {isSubmitting ? "Memproses..." : "Konfirmasi"}
                     </button>
                  </div>
               </motion.div>
            </div>
         )}
      </AnimatePresence>

      <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; }
      `}</style>
    </div>
    );
  }
  